1	{"nl": "I want to make a new empty text file called notes on my desktop", "bash": "touch ~/Desktop/notes.txt", "category": "colloquial"}
2	{"nl": "create an empty file named todo in my documents folder", "bash": "touch ~/Documents/todo.txt", "category": "colloquial"}
