{"nl": "make a folder private", "bash": "chmod 700 ~/Documents/private", "category": "colloquial"}
{"nl": "make file readable by everyone", "bash": "chmod 644 ~/Documents/share.txt", "category": "colloquial"}
{"nl": "see who owns a file", "bash": "ls -l ~/Documents/report.pdf", "category": "colloquial"}
{"nl": "change owner of a file", "bash": "chown $USER:$USER ~/Documents/file.txt", "category": "colloquial"}
{"nl": "preserve dates when copying", "bash": "cp -p ~/Documents/report.pdf ~/backups/", "category": "colloquial"}
{"nl": "back up to external drive", "bash": "rsync -av ~/Documents/ /mnt/external/Documents/", "category": "colloquial"}
{"nl": "show all hidden files", "bash": "ls -la ~", "category": "colloquial"}
{"nl": "make a file hidden", "bash": "mv ~/Documents/notes.txt ~/Documents/.notes.txt", "category": "colloquial"}
{"nl": "see file content with line numbers", "bash": "less -N ~/Documents/code.py", "category": "colloquial"}
{"nl": "concatenate two files", "bash": "cat ~/Documents/part1.txt ~/Documents/part2.txt > ~/Documents/combined.txt", "category": "colloquial"}
{"nl": "split a file into smaller pieces", "bash": "split -b 100M ~/Videos/largevideo.mp4 ~/Videos/part_", "category": "colloquial"}
{"nl": "join split files back together", "bash": "cat ~/Videos/part_* > ~/Videos/combined.mp4", "category": "colloquial"}
{"nl": "make a copy with todays date in name", "bash": "cp ~/Documents/report.pdf ~/Documents/report_$(date +%Y%m%d).pdf", "category": "colloquial"}
{"nl": "back up file with timestamp", "bash": "cp ~/.bashrc ~/.bashrc.bak.$(date +%Y%m%d-%H%M%S)", "category": "colloquial"}
{"nl": "move all photos taken in march", "bash": "find ~/Pictures -type f -newermt 2026-03-01 ! -newermt 2026-04-01 -exec mv {} ~/Pictures/march/ \\;", "category": "colloquial"}
{"nl": "copy everything except node modules", "bash": "rsync -av --exclude=node_modules/ ~/projects/myapp/ /mnt/backup/myapp/", "category": "colloquial"}
{"nl": "copy folder but skip git data", "bash": "rsync -av --exclude=.git/ ~/projects/myapp/ ~/backups/myapp/", "category": "colloquial"}
{"nl": "open the file manager here", "bash": "xdg-open .", "category": "colloquial"}
{"nl": "see who modified this file last", "bash": "stat ~/Documents/report.pdf", "category": "colloquial"}
{"nl": "see when a folder was created", "bash": "stat ~/Documents", "category": "colloquial"}
{"nl": "see file modification times", "bash": "ls -lt --time=mtime ~/Documents/", "category": "colloquial"}
{"nl": "touch a file to update its date", "bash": "touch ~/Documents/notes.txt", "category": "colloquial"}
{"nl": "create a file with a specific date", "bash": "touch -d '2026-01-01 09:00:00' ~/Documents/backdated.txt", "category": "colloquial"}
{"nl": "save the screen output to file", "bash": "ls -la ~ > ~/Documents/listing.txt", "category": "colloquial"}
{"nl": "show me the contents and save them too", "bash": "ls -la ~ | tee ~/Documents/listing.txt", "category": "colloquial"}
{"nl": "calculate the md5 of a file", "bash": "md5sum ~/Downloads/installer.iso", "category": "colloquial"}
{"nl": "verify a downloaded file checksum", "bash": "sha256sum -c ~/Downloads/checksums.sha256", "category": "colloquial"}
{"nl": "calculate sha256 of a file", "bash": "sha256sum ~/Downloads/installer.iso", "category": "colloquial"}
{"nl": "see all files larger than 1 gigabyte", "bash": "find ~ -type f -size +1G 2>/dev/null", "category": "colloquial"}
{"nl": "make a folder for each year", "bash": "mkdir -p ~/Documents/{2023,2024,2025,2026}", "category": "colloquial"}
{"nl": "set up project structure", "bash": "mkdir -p ~/projects/newapp/{src,tests,docs,scripts}", "category": "colloquial"}
{"nl": "convert all images to png", "bash": "for f in ~/Pictures/*.jpg; do convert \"$f\" \"${f%.jpg}.png\"; done", "category": "colloquial"}
{"nl": "rename file extension to lowercase", "bash": "for f in ~/Pictures/*.JPG; do mv \"$f\" \"${f%.JPG}.jpg\"; done", "category": "colloquial"}
{"nl": "delete all log files in a folder", "bash": "rm ~/projects/myapp/logs/*.log", "category": "colloquial"}
{"nl": "delete log files older than 30 days", "bash": "find ~/projects/myapp/logs -name '*.log' -mtime +30 -delete", "category": "colloquial"}
{"nl": "save a copy before editing", "bash": "cp ~/.config/myapp/settings.json ~/.config/myapp/settings.json.bak", "category": "colloquial"}
{"nl": "list only directories in this folder", "bash": "ls -d ~/Documents/*/", "category": "colloquial"}
{"nl": "show file size in human readable", "bash": "ls -lh ~/Downloads/movie.mp4", "category": "colloquial"}
{"nl": "make a hidden config folder", "bash": "mkdir ~/.config/myapp", "category": "colloquial"}
{"nl": "find broken shortcuts", "bash": "find ~ -xtype l 2>/dev/null", "category": "colloquial"}
